                    Ok(ev) => controller.on_exchange(&mut client, ev, clock.now()),
                    Err(e) => say(format!("ignored a kernel event: {e}")),
                },
            }
        }
        if client.take_events_lost() {
            // Handshake messages are retransmitted, so a lost event heals itself.
            say("kernel events were lost; waiting for retransmission".into());
        }
